Record blk (s : mstate) (lo hi : Z) : Prop := BLK {
  blk_bounds : 0 <= lo /\ lo <= hi /\ hi < 2^64;
  blk_win : hi <= ms_lo s \/ ms_hi s <= lo;
  blk_zonE : hi <= IMG_LO \/ IMG_HI <= lo;
  blk_def : forall a : word, lo <= u a < hi -> ms_mem s a <> None
}.

